package io.tornado.optimization;
import io.tornado.api.ReportService;import io.tornado.datafetch.BinanceMarketDataClient;import io.tornado.persistence.*;import io.tornado.strategies.*;import org.slf4j.*;import org.springframework.stereotype.Service;import org.ta4j.core.BarSeries;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class ProfileResearchService{private static final Logger log=LoggerFactory.getLogger(ProfileResearchService.class);private static final int WARMUP_BARS=80;private final BinanceMarketDataClient market;private final CoinRepository coins;private final AppSettingsRepository settings;private final ProfileSelectionService selection;private final WalkForwardProfileSelector selector=new WalkForwardProfileSelector();public ProfileResearchService(BinanceMarketDataClient m,CoinRepository c,AppSettingsRepository s,ProfileSelectionService selection){market=m;coins=c;settings=s;this.selection=selection;}
 public ResearchResult research(ProfileScope scope,String coinSymbol,String strategyCode,long horizon,Instant from,Instant to){ReportService.requireSupportedHorizon(horizon);StrategyDefinition strategy=StrategyDefinition.valueOf(strategyCode);List<Coin>universe;if(scope==ProfileScope.COIN_SPECIFIC){if(coinSymbol==null||coinSymbol.isBlank())throw new IllegalArgumentException("coin is required for a coin-specific profile");universe=List.of(coins.findBySymbolIgnoreCase(coinSymbol).orElseThrow());}else universe=coins.findAllByActiveTrueOrderBySymbol();if(universe.isEmpty())throw new IllegalStateException("No active coins are available for research");if(from==null)from=to.minus(horizon<=3600?Duration.ofDays(90):Duration.ofDays(365));if(!to.isAfter(from))throw new IllegalArgumentException("research end must follow start");AppSettings configuration=settings.findById(1).orElseThrow();Duration snapshotInterval=Duration.ofSeconds(configuration.getSnapshotIntervalSeconds());Map<WalkForwardProfileSelector.Configuration,List<WalkForwardProfileSelector.Observation>>data=new LinkedHashMap<>();List<String>errors=new ArrayList<>();for(Coin coin:universe){BarSeries executionSeries;try{executionSeries=market.historicalCandles(coin.getPair(),"1m",from.minus(Duration.ofMinutes(2)),to);}catch(Exception e){errors.add(coin.getSymbol()+"/execution-1m: "+e.getMessage());log.warn("Profile research skipped {} execution timeline: {}",coin.getPair(),e.getMessage());continue;}for(String timeframe:StrategyProfilePolicy.candidateTimeframes(horizon)){Duration warmup=StrategyProfilePolicy.duration(timeframe).multipliedBy(WARMUP_BARS);try{BarSeries series=market.historicalCandles(coin.getPair(),timeframe,from.minus(warmup),to);for(String parameters:strategy.parameterKeys()){var key=new WalkForwardProfileSelector.Configuration(timeframe,parameters);data.computeIfAbsent(key,x->new ArrayList<>()).addAll(observations(coin,strategy,parameters,horizon,from,to,snapshotInterval,series,executionSeries));}}catch(Exception e){errors.add(coin.getSymbol()+"/"+timeframe+": "+e.getMessage());log.warn("Profile research skipped {} {}: {}",coin.getPair(),timeframe,e.getMessage());}}}int minimum=scope==ProfileScope.GLOBAL?configuration.getMinimumConfigurationSamples():configuration.getCoinProfileMinimumSamples();List<WalkForwardProfileSelector.CandidateEvaluation>ranked=selector.rank(data,minimum,configuration.getProfileResearchRoundTripCostPercent().doubleValue());var winner=ranked.stream().filter(WalkForwardProfileSelector.CandidateEvaluation::eligible).findFirst().orElse(null);ProfileSelectionService.Selection applied=winner==null?new ProfileSelectionService.Selection(false,"No candidate met chronological sample requirements",null):selection.apply(winner,scope,scope==ProfileScope.COIN_SPECIFIC?universe.getFirst():null,strategy.code(),strategy.version(),horizon);return new ResearchResult(scope,scope==ProfileScope.COIN_SPECIFIC?universe.getFirst().getSymbol():null,strategy.code(),horizon,from,to,ranked,applied,errors);}
 List<WalkForwardProfileSelector.Observation>observations(Coin coin,StrategyDefinition strategy,String parameters,long horizon,Instant from,Instant to,Duration snapshotInterval,BarSeries analysis,BarSeries execution){List<WalkForwardProfileSelector.Observation>out=new ArrayList<>();int analysisIndex=analysis.getBeginIndex()-1;Instant nextSnapshot=from;for(int executionIndex=execution.getBeginIndex();executionIndex<=execution.getEndIndex();executionIndex++){var executionBar=execution.getBar(executionIndex);Instant executionAt=openTime(executionBar);if(executionAt.isBefore(from)||executionAt.isBefore(nextSnapshot))continue;if(executionAt.isAfter(to))break;nextSnapshot=executionAt.plus(snapshotInterval);while(analysisIndex+1<=analysis.getEndIndex()&&!analysis.getBar(analysisIndex+1).getEndTime().isAfter(executionAt))analysisIndex++;if(analysisIndex<analysis.getBeginIndex()+WARMUP_BARS)continue;Instant targetAt=executionAt.plusSeconds(horizon);if(targetAt.isAfter(to))break;int targetIndex=findExecutionAtOrAfter(execution,targetAt,executionIndex+1);if(targetIndex<0)break;var signal=strategy.evaluateAt(analysis,parameters,analysisIndex);if(signal.direction()==Direction.NEUTRAL)continue;BigDecimal entry=new BigDecimal(executionBar.getOpenPrice().toString()),exit=new BigDecimal(execution.getBar(targetIndex).getOpenPrice().toString());out.add(new WalkForwardProfileSelector.Observation(coin.getId(),analysis.getBar(analysisIndex).getEndTime(),executionAt,targetAt,signal.direction(),entry,exit));}return out;}
 private int findExecutionAtOrAfter(BarSeries series,Instant target,int start){for(int i=Math.max(start,series.getBeginIndex());i<=series.getEndIndex();i++)if(!openTime(series.getBar(i)).isBefore(target))return i;return-1;}
 private Instant openTime(org.ta4j.core.Bar bar){return bar.getEndTime().minus(bar.getTimePeriod()).plusMillis(1);}
 public record ResearchResult(ProfileScope scope,String coin,String strategyCode,long horizon,Instant from,Instant to,List<WalkForwardProfileSelector.CandidateEvaluation>candidates,ProfileSelectionService.Selection selection,List<String>errors){}
}
